import{_ as p,r as s,o,c,e as n,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"File Attachments - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Creating New Attachments","slug":"creating-new-attachments","link":"#creating-new-attachments","children":[{"level":3,"title":"Handling Multiple Attachments","slug":"handling-multiple-attachments","link":"#handling-multiple-attachments","children":[]}]},{"level":2,"title":"Viewing Attachments","slug":"viewing-attachments","link":"#viewing-attachments","children":[{"level":3,"title":"Accessing the Local Path","slug":"accessing-the-local-path","link":"#accessing-the-local-path","children":[]}]},{"level":2,"title":"Resizing Thumbs","slug":"resizing-thumbs","link":"#resizing-thumbs","children":[]},{"level":2,"title":"Output and Download","slug":"output-and-download","link":"#output-and-download","children":[]},{"level":2,"title":"Usage Example","slug":"usage-example","link":"#usage-example","children":[]},{"level":2,"title":"Validation Example","slug":"validation-example","link":"#validation-example","children":[]}],"relativePath":"3.x/extend/database/attachments.md","filePath":"3.x/extend/database/attachments.md"}'),u={name:"3.x/extend/database/attachments.md"};function r(k,a,d,g,h,m){const t=s("pre-heading"),e=s("post-heading");return o(),c("div",null,[n(t),a[0]||(a[0]=l("h1",null,"File Attachments",-1)),n(e),a[1]||(a[1]=i(`<p>Models can support file attachments using a subset of the <a href="./relations.html">polymorphic relationship</a>. The <code>$attachOne</code> or <code>$attachMany</code> relations are designed for linking a file to a database record called &quot;attachments&quot;. In almost all cases the <code>System\\Models\\File</code> model is used to safekeep this relationship where reference to the files are stored as records in the <code>system_files</code> table and have a polymorphic relation to the parent model.</p><p>In the examples below the model has a single Avatar attachment model and many Photo attachment models.</p><p>A single file attachment:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$attachOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;avatar&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Multiple file attachments:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$attachMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;photos&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block warning"><p>To avoid a naming collision, make sure that your model&#39;s database table does not already have an attribute that uses the same name as your attachment relationship.</p></div><p>Protected attachments are uploaded to the application&#39;s <strong>uploads/protected</strong> directory which is not accessible for the direct access from the Web. A protected file attachment is defined by setting the <code>public</code> property to <code>false</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$attachOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;avatar&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;public&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="creating-new-attachments"><a href="#creating-new-attachments" class="header-anchor">#</a> Creating New Attachments</h2><p>For singular attach relations (<code>$attachOne</code>), you may create an attachment directly via the model relationship, by setting its value using the <code>files</code> function, which reads the file data from an input upload.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file_input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To associate a new file from a local path, use the <code>System\\Models\\File</code> model and <code>fromFile</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromFile</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/path/to/somefile.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To create a file directly from (raw) data, use the <code>fromData</code> method to pass the contents (first argument) and a file name (second argument).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromData</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Some content&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;sometext.txt&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You can also add a file from a URL using the <code>fromUrl</code> method. To use this method, you need install cURL PHP Extension.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromUrl</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;https://example.tld/path/to/avatar.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Optionally, you may specify a custom file name (second argument).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromUrl</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;https://example.tld/avatar.jpg&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;customname.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="handling-multiple-attachments"><a href="#handling-multiple-attachments" class="header-anchor">#</a> Handling Multiple Attachments</h3><p>For multiple attach relations (<code>$attachMany</code>), you can pass an array of values from the <code>files()</code> function.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">photos</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword type-casting">array</span><span class="token punctuation">)</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;multi_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may use the <code>create</code> method to append a file on an existing relationship instead, notice the file object is associated to the <code>data</code> attribute. This approach can be used for singular relations too, if you prefer.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">photos</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;data&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file_input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may use the <code>add</code> method on the relationship to work directly with a <code>System\\Models\\File</code> model.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">photos</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">photos</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromFile</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/path/to/somefile.jpg&#39;</span><span class="token punctuation">)</span>
<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Alternatively, you can prepare a File model before hand, then manually associate the relationship later. Notice the <code>is_public</code> attribute must be set explicitly using this approach.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$file</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token punctuation">;</span>
<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">data</span> <span class="token operator">=</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file_input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">is_public</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">photos</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$file</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="viewing-attachments"><a href="#viewing-attachments" class="header-anchor">#</a> Viewing Attachments</h2><p>The <code>getUrl</code> method returns the full URL of an uploaded public file. The following code would print something like <strong>example.tld/uploads/public/path/to/avatar.jpg</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">getUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Returning multiple attachment file paths.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">photos</span> <span class="token keyword">as</span> <span class="token variable">$photo</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$photo</span><span class="token operator">-&gt;</span><span class="token function">getUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Displaying a file on the page using Twig.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> model<span class="token punctuation">.</span>avatar<span class="token punctuation">.</span>url <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">alt</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Description Image<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><h3 id="accessing-the-local-path"><a href="#accessing-the-local-path" class="header-anchor">#</a> Accessing the Local Path</h3><p>The <code>getLocalPath</code> method will return an absolute path of an uploaded file in the local filesystem. If using an external driver such as S3, this method will download the contents to a temporary location in the local filesystem.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">getLocalPath</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="resizing-thumbs"><a href="#resizing-thumbs" class="header-anchor">#</a> Resizing Thumbs</h2><p>You can resize an image with the <code>getThumbUrl</code> method. The method takes 3 parameters - image width, image height and the options parameter.</p><p>The <strong>width</strong> and <strong>height</strong> parameters should be specified as a number or as the <strong>auto</strong> word for the automatic proportional scaling.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">getThumbUrl</span><span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;mode&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;crop&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Displaying an image on the page using Twig.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> model<span class="token punctuation">.</span>avatar<span class="token punctuation">.</span>thumbUrl<span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> mode<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>exact<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> quality<span class="token punctuation">:</span> <span class="token number">80</span><span class="token punctuation">,</span> extension<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>webp<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">alt</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Description Image<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>Read more about the available options for <code>getThumbUrl</code> on the <a href="./../services/resizer.html">image resizer article</a>.</p><h2 id="output-and-download"><a href="#output-and-download" class="header-anchor">#</a> Output and Download</h2><p>To output the file contents directly, use the <code>output</code> method, this return a <a href="./../services/response-view.html">response object</a> that will include the necessary headers for displaying the file in a browser.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">output</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You can output the contents to the browser by chaining the <code>send</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">output</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Return the <code>download</code> method to download the file as a response.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="usage-example"><a href="#usage-example" class="header-anchor">#</a> Usage Example</h2><p>This section shows a full usage example of the model attachments feature - from defining the relation in a model to displaying the uploaded image on a page.</p><p>Inside your model define a relationship to the <code>System\\Models\\File</code> class, for example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$attachOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;featured_image&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Build a form for uploading a file:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;files&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>example_file<span class="token punctuation">&quot;</span></span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>file<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Upload File<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>Process the uploaded file on the server and attach it to a model:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Find the Blog Post model</span>
<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Save the featured image of the Blog Post model</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">hasFile</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;example_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">featured_image</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;example_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Alternatively, you can use <a href="./relations.html">deferred binding</a> to defer the relationship.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Find the Blog Post model</span>
<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Look for the postback data &#39;example_file&#39; in the HTML form above</span>
<span class="token variable">$fileFromPost</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;example_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// If it exists, save it as the featured image with a deferred session key</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$fileFromPost</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">featured_image</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;data&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$fileFromPost</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Display the uploaded file on a page:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>
<span class="token comment">// Find the Blog Post model again</span>
<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Look for the featured image address, otherwise use a default one</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">featured_image</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$featuredImage</span> <span class="token operator">=</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">featured_image</span><span class="token operator">-&gt;</span><span class="token function">getUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">else</span> <span class="token punctuation">{</span>
    <span class="token variable">$featuredImage</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;http://placehold.it/220x300&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token delimiter important">?&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$featuredImage</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">alt</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Featured Image<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>If you need to access the owner of a file, you can use the <code>attachment</code> property of the <code>File</code> model:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$morphTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;attachment&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">attachment</span><span class="token punctuation">;</span>
</code></pre></div><p>For more information read the <a href="./relations.html#relation-polymorphic-relations">polymorphic relationships</a></p><h2 id="validation-example"><a href="#validation-example" class="header-anchor">#</a> Validation Example</h2><p>The example below uses <a href="./../services/validation.html">array validation</a> to validate <code>$attachMany</code> relationships.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Model</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Gallery</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Validation</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$attachMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;photos&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">File</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;photos&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;photos.*&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;image&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;max:1000&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;dimensions:min_width=100,min_height=100&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>For more information on the <code>attribute.*</code> syntax used above, see the <a href="./../services/validation.html">validation article</a> on validating arrays.</p>`,74))])}const y=p(u,[["render",r]]);export{v as __pageData,y as default};
